// Single endpoint handles both reads and writes. A read request has
// no notification fields in the body; a write has at least one. We
// strip any client_id the caller sends (defence-in-depth — server
// re-derives from the session row).
const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};
const auth = headers['authorization'] || headers['Authorization'] || '';
const token = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
if (!token) return { json: { ok: false, status: 401, error: 'Missing session token' } };
// Detect intent
const writeKeys = ['notification_email','daily_digest_opt_in','booking_alerts_opt_in','calendly_link'];
const isWrite = writeKeys.some(k => Object.prototype.hasOwnProperty.call(body, k));
const payload = {};
if (isWrite) {
  if (typeof body.notification_email === 'string') {
    const e = String(body.notification_email).trim().toLowerCase();
    if (e && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)) return { json: { ok: false, status: 400, error: 'Invalid notification email' } };
    payload.notification_email = e || null;
  }
  if (typeof body.daily_digest_opt_in === 'boolean')   payload.daily_digest_opt_in   = body.daily_digest_opt_in;
  if (typeof body.booking_alerts_opt_in === 'boolean') payload.booking_alerts_opt_in = body.booking_alerts_opt_in;
  if (typeof body.calendly_link === 'string') {
    const link = String(body.calendly_link).trim();
    if (link && link.indexOf('http') !== 0) return { json: { ok: false, status: 400, error: 'Booking link must start with https:// (paste your full Calendly or Cal.com link)' } };
    payload.calendly_link = link || null;
  }
}
return { json: { token, isWrite, payload } };

const rows = $input.item.json;
const row = Array.isArray(rows) ? (rows[0] || null) : (rows && (rows.id || rows.user_id) ? rows : null);

// Product entitlement. validate_session_for_product decides it centrally;
// this line only surfaces the verdict. Without it a 403
// product_not_entitled would be flattened into a 401 by the row check
// below, and a customer who had not bought Sales Engine would be told
// their session was invalid.
if (rows && rows.ok === false) return { json: { ok: false, status: rows.status || 401, error: rows.error, product: rows.product || null } };

const input = $('Parse Request').item.json;
if (!row) return { json: { ok: false, status: 401, error: 'Invalid or expired session' } };
if (row.user_role !== 'client' && row.user_role !== 'team_member') return { json: { ok: false, status: 403, error: 'Client access required' } };
if (!row.client_id) return { json: { ok: false, status: 403, error: 'No client mapped to session' } };
// team_members are read-only for now — only the primary client login can mutate prefs
if (input.isWrite && row.user_role !== 'client') return { json: { ok: false, status: 403, error: 'Only the primary account can change settings' } };
return { json: { ok: true, client_id: row.client_id, isWrite: input.isWrite, payload: input.payload } };

// Read the row back whatever shape it arrives in.
//
// This used to be:
//   const rows = Array.isArray($input.item.json) ? $input.item.json : [];
// n8n splits an array response into separate items, so $input.item.json
// is the ROW, not an array containing it. Array.isArray was therefore
// false on every successful read, rows became [], and the endpoint
// answered ok:true with client:null -- a healthy-looking response that
// said the customer has no settings. The Settings page rendered blank
// and there was no error anywhere to explain it.
//
// allOf() is the house pattern for this (see CLAUDE.md); it handles both
// the split and unsplit shapes, and drops the empty item alwaysOutputData
// emits when a read genuinely returns nothing.
const allOf = function (name) {
  try {
    const items = $(name).all().map(function (i) { return i.json; });
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    return items.filter(function (o) {
      return o && typeof o === 'object' && Object.keys(o).length > 0;
    });
  } catch (e) { return []; }
};
const rows = allOf('Read Settings');
return { json: { ok: true, client: rows[0] || null } };
